import math


def composite_trapezoid(f, a, b, n):
    """Composite trapezoid rule with n panels on [a, b]."""
    if n < 1:
        raise ValueError("n must be >= 1")
    h = (b - a) / n
    total = 0.5 * (f(a) + f(b))
    for i in range(1, n):
        total += f(a + i * h)
    return total * h


def composite_simpson(f, a, b, n):
    """Composite Simpson rule with n panels (n must be even) on [a, b]."""
    if n < 2 or n % 2 != 0:
        raise ValueError("n must be an even integer >= 2")
    h = (b - a) / n
    total = f(a) + f(b)
    for i in range(1, n):
        x = a + i * h
        weight = 4.0 if i % 2 == 1 else 2.0
        total += weight * f(x)
    return total * h / 3.0


def _simpson(f, a, b):
    """Plain Simpson rule on [a, b] (3 function evaluations)."""
    return (b - a) / 6.0 * (f(a) + 4.0 * f(0.5 * (a + b)) + f(b))


def _adaptive_simpson_rec(f, a, b, tol, whole):
    mid = 0.5 * (a + b)
    left = _simpson(f, a, mid)
    right = _simpson(f, mid, b)
    if abs(left + right - whole) <= 15.0 * tol:
        return left + right + (left + right - whole) / 15.0
    return (_adaptive_simpson_rec(f, a, mid, 0.5 * tol, left)
            + _adaptive_simpson_rec(f, mid, b, 0.5 * tol, right))


def adaptive_simpson(f, a, b, tol):
    """Adaptive Simpson quadrature on [a, b] with absolute tolerance `tol`.

    Returns the integral estimate.
    """
    whole = _simpson(f, a, b)
    return _adaptive_simpson_rec(f, a, b, tol, whole)
